  bool use_exp = false;
  if (fspecs.format == float_format::exp) {
    use_exp = true;
  } else if (fspecs.format == float_format::general) {
    const int exp_lower = -4, exp_upper = 16;
    if (output_exp < exp_lower) {
      use_exp = true;
    } else if (fspecs.precision > 0) {
      if (output_exp >= fspecs.precision) use_exp = true;
    } else if (output_exp >= exp_upper) {
      use_exp = true;
    }
